def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The marker is the 2x2 all-zero square.
    top = left = None
    for r in range(h - 1):
        for c in range(w - 1):
            if all(g[rr][cc] == 0 for rr in (r, r + 1) for cc in (c, c + 1)):
                top, left = r, c
                break
        if top is not None:
            break
    if top is None:
        return g
    # Continue the empty square's columns through the grid; in its two rows,
    # retain only cells of color 2.
    for r in range(h):
        for c in (left, left + 1):
            g[r][c] = 0
    for r in (top, top + 1):
        for c in range(w):
            if g[r][c] != 2:
                g[r][c] = 0
    return g

